import json,pathlib,collections,hashlib
R=pathlib.Path('artifacts/final-ux-review')
m=json.loads((R/'manifest.json').read_text()); by={x['id']:x for x in m}
issues=[]
def issue(id,priority,title,kind,evidence,observation,impact,recommendation):
 issues.append(dict(id=id,priority=priority,title=title,type=kind,evidence=[x for x in evidence if x in by],observation=observation,impact=impact,recommendation=recommendation))
